{"files": [{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "宋远桥",
      "role": "protagonist",
      "identity": "个体户/倒爷，无固定户口，骑嘉陵摩托穿州过省倒卖货物",
      "traits": ["孤注一掷", "闷骚（不善表达感情）", "精明但重义", "野蛮生长的生命力", "宿命感"],
      "overt_motivation": "做成这单南货北运的生意翻身",
      "covert_motivation": "用一个'赚到了'的结果给自己一个娶她的理由——他觉得自己配不上她",
      "secret_fear": "怕她知道真相后看不起他——一个没户口没单位的人，连求婚都得靠赌",
      "misperception_of_other": "以为程漫只是需要这份临时押货工作的钱，不知道她早已把这趟旅程当成人生中最好的日子",
      "hidden_connection": "他在她张贴的'求职启事'前站了三天才开口——他一开始就不是在找押货的人，而是在找一个把她带走的理由"
    },
    {
      "name": "程漫",
      "role": "deuteragonist",
      "identity": "国营棉纺厂下岗女工，26岁，厂里分的宿舍也要收回",
      "traits": ["沉默中的韧性", "务实到骨子里", "细腻但克制", "倔强", "行动力极强"],
      "overt_motivation": "赚一笔路费，想清楚下岗后何去何从",
      "covert_motivation": "想被一个人需要——不是作为工人被工厂需要，而是作为一个人被另一个人需要",
      "secret_fear": "怕旅程结束——一旦到了目的地，雇佣关系就没了，他们就没有理由待在一起",
      "misperception_of_other": "以为宋远桥把她当廉价劳力使，不知道他每个县城买枕巾是在为她准备聘礼",
      "hidden_connection": "她在地图上偷偷画的心，就是她从未说出口的'我愿意'"
    }
  ],
  "supporting_characters": [
    {
      "name": "老彭",
      "function": "反转点",
      "identity": "长途货车司机，四十多岁，跑了十几年长途",
      "description": "在烂路段帮他们搭过一程，临别无意说出'你媳妇挺能吃苦啊'，触发两人关系的微妙转变。代表公路上的人情温度。"
    },
    {
      "name": "税卡人员",
      "function": "阻碍",
      "identity": "路上税卡的工作人员",
      "description": "代表九十年代对个体户的政策压力，查货扣罚，是'赔了'结局的直接推手之一。不设具体姓名，代表一种时代力量。"
    }
  ],
  "relationship_dynamics": "宋远桥和程漫的关系经历四个阶段：雇佣（陌生人的客气）→ 共谋（困境中的战友默契）→ 暧昧（枕巾的秘密、红丝巾、桥洞一夜）→ 定情（赔了之后的命运共同体）。双向暗恋的核心张力在于：他以为自己配不上她所以要靠赚钱证明，她以为他不在意她所以只敢在地图上画心。最终打破僵局的不是谁的告白，而是'赔了'这个结果——当赚钱的幻想破灭，只剩下两个一无所有的人，反而获得了确定彼此的自由。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕：上路——建立雇佣关系，展示1992年的时代质感，完成男女主的第一次关键接触，埋下枕巾线索。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "嘉陵",
        "core_event": "1992年秋，倒爷宋远桥在广东某镇找到下岗女工程漫，雇她押货北上。第一夜他把枕巾放在她枕头下面。",
        "emotional_tone": "粗粝中的微光——尘土、汽油味、陌生人之间小心翼翼的距离",
        "key_scenes": [
          "摩托车前的相遇：他的嘉陵摩托、她手里的求职启事、边斗里的货物",
          "上路：她第一次坐上后座，不知道该抓哪里，最终抓住货物的绳索而非他的腰",
          "第一对枕巾：供销社柜台前，他买下第一对鸳鸯枕巾，她以为是货",
          "第一夜旅店：他睡边斗让她睡床，她发现枕头下面多了一对枕巾"
        ]
      }
    ],
    "turning_point": "她发现他把枕巾放在了她的枕头下面——不像是对待货物的方式。第一次产生疑惑，但没多想。"
  },
  "act_two": {
    "description": "第二幕：在路上——从战友默契到暧昧涌动。七天旅程的第二到第六天。枕巾越积越多，困境越来越大，两个人越来越近。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "枕巾",
        "core_event": "第二天到第四天。经历爆胎、暴雨、税卡盘查。他在暴风雨中停车给她买红丝巾。老彭说'你媳妇挺能吃苦'。她发现边斗里已有七对鸳鸯枕巾，意识到这不是商品。",
        "emotional_tone": "从患难与共到心跳加速——暴雨中的红丝巾是整个旅程的情感拐点",
        "key_scenes": [
          "县城供销社连续买枕巾的蒙太奇：每个柜台、每对枕巾、边斗渐满",
          "爆胎与暴雨：他修车她撑伞，两人在泥水里狼狈却默契",
          "红丝巾（疯点1）：暴风雨中他突然停车，冲进路边小店买红丝巾，'怕你冷'",
          "老彭搭车：货车司机说'你媳妇挺能吃苦啊'，两人都没否认",
          "地图上的心（疯点2）：她趁他不注意，在地图上每经过一个城市画一颗心",
          "中点发现：第四夜她数枕巾——七对，全是鸳鸯图案。她意识到这是仪式，但没说破"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "婚床",
        "core_event": "第五天到第六天。她知道了秘密但装不知道，开始主动帮他算账选路。第六夜桥洞过夜，他铺开所有枕巾说'我们有一万张婚床'。夜里他翻账本，发现大概率赔了。",
        "emotional_tone": "甜到极致的前夜与悬在头顶的刀——浪漫与恐惧同时到达顶峰",
        "key_scenes": [
          "她开始帮他算账、选路线、跟税卡的人周旋——从押货工变成合伙人",
          "整理枕巾：她把枕巾一对一对码整齐，像在整理嫁妆",
          "桥洞之夜（疯点3/高潮预备）：他铺开所有枕巾当床，'现在我们有一万张婚床'",
          "她哭了但没说话，他以为她嫌弃",
          "深夜翻账本：他发现这单大概率赔了，露出真正的恐惧"
        ]
      }
    ],
    "turning_point": "桥洞之夜后他发现算来算去这单必赔——他为她准备的'聘礼之旅'走向了他最恐惧的结局。D22模式的悲剧必然性在此显现：为激情牺牲一切的赌注即将揭晓。"
  },
  "act_three": {
    "description": "第三幕：终点与新起点——赔了。赌局揭晓，他以为一切结束了。但她用卖摩托的钱买了两张去深圳的车票，完成了真正的'定情'。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "车票",
        "core_event": "第七天到达目的地，确认赔了。他说出赌约'赚了娶你，赔了摩托归你我归摩托'。她卖了摩托买两张去深圳的车票。火车站长椅上她展开画满心的地图，他看见了。他们带着最后一对枕巾上车，往南。",
        "emotional_tone": "从悲壮到释然到温暖到新生——情感的四重翻转在最后一章完成",
        "key_scenes": [
          "交货谈价：确认赔了三百多，七天白跑",
          "摩托旁的告白：他抽烟说出赌约，声音很平但手在抖",
          "她的沉默与反击：'摩托值多少？''够买两张去深圳的火车票。'",
          "卖摩托：他看着嘉陵被人骑走，像送走了半条命",
          "火车站长椅：她展开地图，他看见每个城市旁边的心",
          "封蜡结尾：最后一对枕巾塞进行李包，鸳鸯图案露出一角。火车来了。往南。"
        ]
      }
    ],
    "turning_point": "她把摩托卖了买车票——这是对他'赔了我归摩托'的终极回应：你不能归摩托，因为摩托已经变成了我们的未来。D22模式在此被反转：他以为牺牲一切就是死在路上，她告诉他牺牲一切是两个人一起从零开始。"
  }
}"}]}

